import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    N = int(input_data[0])
    K = int(input_data[1])

    total = 0
    remainder = 0
    while remainder * 2 < K:
        if (remainder * 2) % K == 0:
            count = N // K + (1 if remainder <= N % K else 0)
            total += count * count * count
        remainder += 1

    if K % 2 == 0:
        mid = K // 2
        if mid * 2 % K == 0:
            count = N // K + (1 if mid <= N % K else 0)
            total += count * count * count

    print(total)

if __name__ == "__main__":
    solve()
